const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');
const { app } = require('electron');

const dbPath = app && app.isPackaged
  ? path.join(app.getPath('userData'), 'pharmacy.db')
  : path.join(__dirname, '../../../pharmacy.db');

if (app && app.isPackaged) {
  const dbDir = path.dirname(dbPath);
  if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
  }
}

const db = new Database(dbPath);

db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

function initDatabase() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS suppliers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      supplier_name TEXT NOT NULL UNIQUE,
      contact_person TEXT,
      phone TEXT,
      email TEXT,
      address TEXT
    );

    CREATE TABLE IF NOT EXISTS drugs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      brand_name TEXT NOT NULL UNIQUE,
      generic_name TEXT,
      category TEXT,
      min_stock_alert INTEGER DEFAULT 10
    );

    CREATE TABLE IF NOT EXISTS batches (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      drug_id INTEGER NOT NULL,
      supplier_id INTEGER,
      batch_number TEXT NOT NULL,
      expiry_date TEXT NOT NULL,
      buy_price REAL NOT NULL,
      sell_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (drug_id) REFERENCES drugs(id) ON DELETE CASCADE,
      FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL,
      UNIQUE(drug_id, batch_number)
    );

    CREATE TABLE IF NOT EXISTS purchase_orders (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      supplier_id INTEGER NOT NULL,
      order_date DATETIME DEFAULT CURRENT_TIMESTAMP,
      status TEXT DEFAULT 'PENDING',
      total_cost REAL NOT NULL,
      FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS sales (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      shift_id INTEGER,
      shift_invoice_no INTEGER DEFAULT 1,
      total_amount REAL NOT NULL,
      discount REAL DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS sale_items (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sale_id INTEGER NOT NULL,
      batch_id INTEGER,
      drug_name TEXT,
      batch_number TEXT,
      buy_price REAL DEFAULT 0,
      quantity INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      total_price REAL NOT NULL,
      FOREIGN KEY (sale_id) REFERENCES sales(id)
    );

    CREATE TABLE IF NOT EXISTS prescriptions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sale_id INTEGER NOT NULL,
      patient_name TEXT NOT NULL,
      patient_phone TEXT,
      doctor_name TEXT NOT NULL,
      prescription_no TEXT NOT NULL,
      notes TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS till_shifts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      opened_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      closed_at DATETIME,
      opening_float REAL NOT NULL,
      total_sales REAL DEFAULT 0,
      total_orders INTEGER DEFAULT 0,
      total_discounts REAL DEFAULT 0,
      expected_cash REAL DEFAULT 0,
      actual_cash REAL DEFAULT 0,
      variance REAL DEFAULT 0,
      note TEXT,
      status TEXT DEFAULT 'OPEN'
    );

    CREATE TABLE IF NOT EXISTS audit_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      action TEXT NOT NULL,
      details TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    INSERT OR IGNORE INTO settings (key, value) VALUES 
      ('pharmacy_name', 'NEW SAHASNA PHARMACY'),
      ('pharmacy_address', 'No.514, Walagedara, Balapitiya'),
      ('pharmacy_phone', '077-6723395'),
      ('admin_pin', '1234');
  `);

  try { db.exec(`ALTER TABLE sales ADD COLUMN discount REAL DEFAULT 0;`); } catch (e) { }
  try { db.exec(`ALTER TABLE sales ADD COLUMN shift_id INTEGER;`); } catch (e) { }
  try { db.exec(`ALTER TABLE sales ADD COLUMN shift_invoice_no INTEGER;`); } catch (e) { }
  try { db.exec(`ALTER TABLE sale_items ADD COLUMN drug_name TEXT;`); } catch (e) { }
  try { db.exec(`ALTER TABLE sale_items ADD COLUMN batch_number TEXT;`); } catch (e) { }
  try { db.exec(`ALTER TABLE sale_items ADD COLUMN buy_price REAL DEFAULT 0;`); } catch (e) { }
  try { db.exec(`ALTER TABLE batches ADD COLUMN supplier_id INTEGER;`); } catch (e) { }
  try { db.exec(`ALTER TABLE drugs ADD COLUMN barcode TEXT;`); } catch (e) { }
  try { db.exec(`ALTER TABLE batches ADD COLUMN barcode TEXT;`); } catch (e) { }
  try {
    const batchCols = db.prepare(`PRAGMA table_info(batches)`).all();
    const hasCreatedAt = batchCols.some(c => c.name === 'created_at');
    if (!hasCreatedAt) {
      db.exec(`ALTER TABLE batches ADD COLUMN created_at TEXT;`);
    }
    db.exec(`
      UPDATE batches 
      SET created_at = (
        SELECT MIN(s.created_at) 
        FROM sales s 
        JOIN sale_items si ON si.sale_id = s.id 
        WHERE si.batch_id = batches.id
      )
      WHERE created_at IS NULL AND EXISTS (
        SELECT 1 FROM sale_items si WHERE si.batch_id = batches.id
      );
    `);
    db.exec(`UPDATE batches SET created_at = datetime('now', 'localtime') WHERE created_at IS NULL;`);
  } catch (e) {
    try {
      db.exec(`ALTER TABLE batches ADD COLUMN created_at TEXT;`);
      db.exec(`UPDATE batches SET created_at = datetime('now', 'localtime') WHERE created_at IS NULL;`);
    } catch (e2) { }
  }

  // FIX: Automatically backfill missing buy prices from batches table for past sales
  try {
    db.exec(`
      UPDATE sale_items 
      SET buy_price = (
        SELECT b.buy_price FROM batches b 
        WHERE b.id = sale_items.batch_id 
           OR (sale_items.batch_id IS NULL AND b.batch_number = sale_items.batch_number)
        LIMIT 1
      )
      WHERE (buy_price IS NULL OR buy_price <= 0);
    `);
  } catch (e) { }
}

